class Timeout(Exception):
    pass


class HttpError(Exception):
    def __init__(self, status):
        self.status = status
        super().__init__(f"HTTP {status}")


BACKOFF = [0.0, 0.1, 0.4]


def request(send, retries=2):
    """send() returns a body or raises Timeout / HttpError."""
    attempt = 0
    while True:
        try:
            return send()
        except Exception:
            if attempt >= retries:
                raise
            attempt += 1

