import pytest

from client import HttpError, Timeout, request


def test_success_passes_through():
    assert request(lambda: "ok") == "ok"


def test_retries_timeout_then_succeeds():
    calls = {"n": 0}

    def send():
        calls["n"] += 1
        if calls["n"] < 3:
            raise Timeout()
        return "ok"

    assert request(send, retries=2) == "ok"
    assert calls["n"] == 3


def test_retries_5xx():
    calls = {"n": 0}

    def send():
        calls["n"] += 1
        if calls["n"] < 2:
            raise HttpError(503)
        return "ok"

    assert request(send, retries=2) == "ok"


def test_does_not_retry_4xx():
    calls = {"n": 0}

    def send():
        calls["n"] += 1
        raise HttpError(404)

    with pytest.raises(HttpError):
        request(send, retries=3)
    assert calls["n"] == 1, "a client error must not be retried"


def test_backoff_sequence_intact():
    import client
    assert client.BACKOFF == [0.0, 0.1, 0.4]

