from states import STATES

ALLOWED = {
    'draft': ['review'],
    'review': ['published', 'draft'],
    'published': [],
}


def can_move(src, dst):
    if src not in STATES or dst not in STATES:
        raise ValueError('unknown state')
    return dst in ALLOWED.get(src, [])

