import threading

from counter import Counter


def test_single_thread():
    c = Counter()
    c.increment()
    c.add(4)
    assert c.value == 5


def test_reset_returns_cleared_value():
    c = Counter()
    c.add(7)
    assert c.reset() == 7
    assert c.value == 0


def test_no_lost_increments():
    c = Counter()

    def worker():
        for _ in range(2000):
            c.increment()

    threads = [threading.Thread(target=worker) for _ in range(10)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    assert c.value == 20000


def test_no_lost_adds():
    c = Counter()

    def worker():
        for _ in range(1000):
            c.add(2)

    threads = [threading.Thread(target=worker) for _ in range(10)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    assert c.value == 20000
